    /*
     * Assign a Workspace
     * 
     * @param	parentId	UUID
     * @param	assignment 	AnalyticsWorkspace 
     * @return	FeatureSet
     */
    public FeatureSet assignWorkspace( UUID parentId, AnalyticsWorkspace assignment ) {
	    LOGGER.info("assigning Workspace as " + assignment.toString() );

	    FeatureSet parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( AnalyticsWorkspace.class, assignment.getAnalyticsWorkspaceId());

	    // ------------------------------------------
		// assign the Workspace to the parent entity
		// ------------------------------------------ 
	    parentEntity.setWorkspace( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Workspace
	 * 
	 * @param	parentId		UUID
	 * @return	FeatureSet
	 */
	public FeatureSet unAssignWorkspace( UUID parentId ) {
		FeatureSet parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Workspace on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Workspace on the parent entithy
		// ------------------------------------------     
	    parentEntity.setWorkspace(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


